window.KEIM_TEAM_DATA={"collections": {"products": {"concretal-black": {"about": "Sol-silicate paint for concrete giving opaque coatings in intense black shades. A selected black pigment gives particularly deep black tones, and the coating protects the concrete from weathering.", "application": "Brush or roller.", "category": "Concrete paint", "clause": "Apply by brush or roller two coats of opaque sol-silicate concrete paint, KEIM Concretal-Black, with selected black pigment for intense black shades, diluted with KEIM Concretal-Fixativ as per the technical data sheet. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "Intense black shades.", "cons": [{"label": "Two coats", "rate": 0.35}], "description": "Opaque, intense-black sol-silicate paint for concrete.", "docs": [], "flag": "", "id": "concretal-black", "name": "KEIM Concretal-Black", "packs": [18, 5], "role": "Base + finish", "sds": "https://www.keim.com.au/_files/ugd/bc139a_88be3087d02f42518d226636e64cf1c8.pdf", "sdsNote": "AU SDS · 01.09.2025", "tds": "https://www.keim.com/documents/en-GB/723/TM_Concretal-Black_EN-EN.pdf", "unit": "kg"}, "concretal-fixativ": {"about": "A combination of liquid potassium silicate and silica sol. The specific diluent for the KEIM Concretal system, and suitable for evening out and reducing the absorbency of concrete surfaces.", "application": "Brush, roller or spray.", "category": "Diluent / primer", "clause": "For the fixing of concrete and to even out the absorption of particularly absorbent substrates: apply by brush, roller or spray one coat of KEIM Concretal-Fixativ, a liquid based on potassium silicate and silica sol, to reduce and regularise the substrate's absorbency before applying KEIM Concretal coatings. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "Clear.", "cons": [{"label": "Primer coat, undiluted", "rate": 0.15}, {"label": "As diluent for Concretal-Lasur, per coat", "rate": 0.03}], "description": "Silicate diluent and primer for concrete. Thins Concretal-Lasur 20–50%.", "docs": [], "flag": "", "id": "concretal-fixativ", "name": "KEIM Concretal-Fixativ", "packs": [20, 5], "role": "Diluent", "sds": "https://www.keim.com.au/_files/ugd/bc139a_efbdf9116a57478dbaaf754dd9174e35.pdf", "sdsNote": "AU SDS · 01.09.2025", "tds": "https://www.keim.com/documents/en-GB/723/TM_Concretal-Fixativ_EN-EN.pdf", "unit": "L"}, "concretal-fsp": {"about": "Fine filler for repairing and restoring concrete on vertical and non-trafficable surfaces. Applied from about 0.5 mm up to 4 mm thick to close pores and shrinkage cavities. Can be sprayed once mixed.", "application": "Trowel, spatula or spray.", "category": "Repair mortar", "clause": "Fill blowholes, pores and shrinkage cavities in the concrete with mineral fine filler KEIM Concretal-FSP 0.2, applied by trowel or spatula at 0.5–4 mm thickness, and allow to cure before coating. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "Grey.", "cons": [{"label": "1 mm thickness", "rate": 1.75}, {"label": "2 mm thickness", "rate": 3.5}, {"label": "3 mm thickness", "rate": 5.25}], "description": "Fine mortar for filling blowholes and skim-coating concrete. 0.5–4 mm.", "docs": [], "flag": "", "id": "concretal-fsp", "name": "KEIM Concretal-FSP 0.2", "packs": [25], "role": "Preparation", "sds": "https://www.keim.com.au/_files/ugd/bc139a_75d11bdfe91241a5b017edcb687db2d0.pdf", "sdsNote": "AU SDS · 05.09.2025", "tds": "https://www.keim.com/data/products/2932/723/TM_Concretal-FSP_0.2_EN-EN.pdf", "unit": "kg"}, "concretal-lasur": {"about": "Sol-silicate glaze for concrete, diluted with KEIM Concretal-Fixativ to give anything from a light transparent glaze to an opaque protective finish. Evens out colour variation on off-form and precast concrete while keeping the concrete character.", "application": "Brush, working into the surface.", "category": "Concrete glaze", "clause": "Apply by brush two coats of sol-silicate concrete glaze, KEIM Concretal-Lasur, diluted with KEIM Concretal-Fixativ to the ratio agreed on the approved trial panel, to achieve a transparent to semi-transparent mineral finish that retains the texture of the concrete. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "KEIM Concretal-Lasur colour range.", "cons": [{"label": "Glaze, 1:10 with Concretal-Fixativ, one coat", "rate": 0.009}, {"label": "Glaze, 1:20 with Concretal-Fixativ, one coat", "rate": 0.005}, {"label": "Glaze, 1:10 with Concretal-Fixativ, two coats", "rate": 0.018}, {"label": "Glaze, 1:20 with Concretal-Fixativ, two coats", "rate": 0.012}, {"label": "Glaze, 1:5 with Concretal-Fixativ, two coats", "rate": 0.033}, {"label": "Opaque", "rate": 0.25}], "description": "Thin-film sol-silicate glaze for concrete. Transparent to opaque depending on dilution.", "docs": [], "flag": "", "id": "concretal-lasur", "name": "KEIM Concretal-Lasur", "packs": [15, 5], "role": "Finish", "sds": "https://www.keim.com.au/_files/ugd/bc139a_15726a804bf14f7395f258a5e4090129.pdf", "sdsNote": "AU SDS · 01.09.2025", "tds": "https://www.keim.com/documents/en-GB/723/TM_Concretal-Lasur_EN-EN.pdf", "unit": "L"}, "contact-plus-grob": {"about": "Coarse filled sol-silicate primer to DIN 18363 2.4.1 for the KEIM Soldalit and KEIM Concretal systems. Evens out structural variations and closes micro-cracks on historic and modern facades and on sound old dispersion or synthetic resin coatings. Aggregate grain size 1 mm.", "application": "Brush.", "category": "Renovation primer", "clause": "Apply by brush one coat of coarse filling silicate primer to DIN 18363 2.4.1 with aggregate grain size 1 mm, KEIM Contact-Plus-Grob, to bridge micro-cracks and even out texture. Dilute with a silicate liquid of the type KEIM Soldalit-Fixativ as per the technical data sheet. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "White, coloured on request.", "cons": [{"label": "One coat, diluted with Soldalit-Fixativ", "rate": 0.5}, {"label": "One coat, diluted with Concretal-Fixativ", "rate": 0.5}], "description": "Coarse fibre primer that bridges cracks up to 1.0 mm.", "docs": [], "flag": "", "id": "contact-plus-grob", "name": "KEIM Contact-Plus-Grob", "packs": [25, 5], "role": "Primer", "sds": "https://www.keim.com.au/_files/ugd/bc139a_d7738bbdc5ad4b95b41d8fda36bb6318.pdf", "sdsNote": "AU SDS · 02.09.2025", "tds": "https://www.keim.com/data/products/975/723/TM_Contact-Plus-Grob_EN-EN.pdf", "unit": "kg"}, "contact-plus": {"about": "Filled sol-silicate primer to DIN 18363 2.4.1 for the KEIM Soldalit and KEIM Concretal systems. Evens out structural differences and closes micro-cracks on historic and modern facades and on sound old dispersion or synthetic resin coatings. Aggregate grain size 0.5 mm.", "application": "Brush.", "category": "Renovation primer", "clause": "Apply preferably by brush one coat of filling silicate primer to DIN 18363 2.4.1 with aggregate grain size 0.5 mm, KEIM Contact-Plus, capable of closing shrinkage cracks and evening out plaster repairs. Water vapour diffusion-equivalent air layer thickness sd approx. 0.02 m, density approx. 1.7 g/cm³ and pH approx. 11.4. Dilute by a maximum of 10–20% with a silicate liquid to DIN 18363 2.4.1 of the type KEIM Soldalit-Fixativ. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "White, coloured on request.", "cons": [{"label": "One coat, diluted with Soldalit-Fixativ", "rate": 0.35}, {"label": "One coat, diluted with Concretal-Fixativ", "rate": 0.35}], "description": "Fibre-reinforced filled bridging primer for mineral substrates and old organic coatings.", "docs": [], "flag": "", "id": "contact-plus", "name": "KEIM Contact-Plus", "packs": [25, 5], "role": "Primer", "sds": "https://www.keim.com.au/_files/ugd/bc139a_61b68d4d1bcd4652b99afe3bb58b7711.pdf", "sdsNote": "AU SDS · 01.09.2025", "tds": "https://www.keim.com/data/products/974/723/TM_Contact-Plus_EN-EN.pdf", "unit": "kg"}, "coolit": {"about": "Sol-silicate facade paint developed to reduce solar heat build-up on dark colours. Dark shades stay significantly cooler than conventional dark paints, which reduces thermal stress on the facade. Based on next-generation silica sol to DIN 18363 2.4.1, and suitable over well-bonded existing organic coatings.", "application": "Brush, roller or airless spray.", "category": "Facade paint", "clause": "Apply by brush or roller two coats of heat-reflective sol-silicate facade paint to DIN 18363 2.4.1, KEIM Coolit, based on a combination of silica sol and potassium silicate solution with near-infrared reflective pigments. Dilute with KEIM Soldalit-Fixativ as per the technical data sheet. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "Dark and intense shades from the KEIM colour range.", "cons": [{"label": "Two coats", "rate": 0.35}, {"label": "One coat", "rate": 0.18}], "description": "Near-infrared reflective sol-silicate paint for dark shades (TSR ≥ 30). Walls only.", "docs": [], "flag": "", "id": "coolit", "name": "KEIM Coolit", "packs": [18, 5, 2.5], "role": "Base + finish", "sds": "https://www.keim.com.au/_files/ugd/bc139a_3a7388e9d2e84e21aa28b7fae7c5bc00.pdf", "sdsNote": "AU SDS · 04.09.2025", "tds": "https://www.keim.com/documents/en-GB/723/TM_Soldalit-Coolit_EN-EN.pdf", "unit": "kg"}, "design-lasur": {"about": "Sol-silicate glaze for interior and exterior use, for high-quality decorative glazes and creative effects over mineral surfaces. Diluting with Design Base or Design Fixativ gives a wide range of glazing effects.", "application": "KEIM glazing brush.", "category": "Decorative glaze", "clause": "Apply by glazing brush KEIM Design-Lasur, a sol-silicate glaze, diluted to the ratio agreed on the approved trial panel, in the number of coats required to achieve the approved decorative glaze effect. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "KEIM Design-Lasur colour range.", "cons": [{"label": "1:5 dilution, one coat", "rate": 0.017}, {"label": "1:20 dilution, one coat", "rate": 0.005}, {"label": "1:5 dilution, two coats", "rate": 0.034}, {"label": "1:20 dilution, two coats", "rate": 0.009}], "description": "Sol-silicate glaze concentrate for decorative finishes on open-pored mineral surfaces.", "docs": [], "flag": "Needs Design-Base or Design-Fixativ to mix. Neither is on the AU range list.", "id": "design-lasur", "name": "KEIM Design-Lasur", "packs": [15, 5], "role": "Finish", "sds": "https://www.keim.com.au/_files/ugd/bc139a_d6556be240fd4799b412e08de035fef7.pdf", "sdsNote": "AU SDS · 02.09.2025", "tds": "https://www.keim.com/documents/en-GB/723/TM_Design-Lasur_EN-EN.pdf", "unit": "L"}, "dispersion-remover": {"about": "Biodegradable paste for removing resin-based paints and plastic coatings, free of aromatic hydrocarbons and chlorinated compounds.", "application": "Brush or roller.", "category": "Paint stripper", "clause": "Remove existing acrylic or dispersion coatings by applying KEIM Dispersion Remover by brush or roller, leaving it to act for the time stated in the technical data sheet, then removing the softened coating by high-pressure water jetting. Allow the substrate to dry. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "", "cons": [{"label": "Dispersion (acrylic) paints", "rate": 0.4}, {"label": "Synthetic resin or plastic renders", "rate": 0.9}], "description": "Paste that strips acrylic and dispersion paints and synthetic renders.", "docs": [], "flag": "", "id": "dispersion-remover", "name": "KEIM Dispersion Remover", "packs": [5], "role": "Preparation", "sds": "https://www.keim.com.au/_files/ugd/bc139a_00ae92e1788249a0a657fa8953682521.pdf", "sdsNote": "AU SDS · 08.12.2025", "tds": "https://www.keim.com.au/_files/ugd/72d69c_84af484b8a524bcea79ff2dcdefd2585.pdf", "unit": "kg"}, "faceal-oleo": {"about": "Clear, permanent water, oil and graffiti protection for porous mineral surfaces such as concrete, render, stone and KEIM silicate coatings.", "application": "Brush, roller or low-pressure spray.", "category": "Anti-graffiti", "clause": "Apply two coats of clear permanent water, oil and graffiti protection, KEIM Faceal Oleo HD, to clean, dry porous mineral surfaces. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "Clear.", "cons": [{"label": "Two coats", "rate": 0.22}, {"label": "One coat", "rate": 0.12}], "description": "Clear permanent water, oil and graffiti protection for porous mineral surfaces.", "docs": [], "flag": "", "id": "faceal-oleo", "name": "KEIM Faceal Oleo HD", "packs": [25], "role": "Protection", "sds": "https://keim-usa.com/wp-content/uploads/2024/07/SDS_2116_FACEAL-OLEO-HD_EN_240710.pdf", "sdsNote": "EU SDS (English) · 10.07.2024 · no AU SDS", "tds": "https://keim-usa.com/wp-content/uploads/2024/07/TDS-Faceal-Oleo-HD-2023.pdf", "unit": "L"}, "innoprim": {"about": "Interior primer and intermediate coat. Reduces and evens out substrate absorption, which extends the open time of the following KEIM interior coats so large areas can be painted without lap marks, even in raking light. Suits mineral and organic substrates, sound old coatings and mixed substrates. Not for timber, varnishes, substrates with salt efflorescence or yellowed plasterboard.", "application": "Brush, roller or airless spray.", "category": "Interior primer", "clause": "Apply by brush, roller or airless spray one coat of interior silicate primer, KEIM Innoprim, to reduce and even out substrate absorbency prior to the KEIM Innostar finish coats. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "White.", "cons": [{"label": "One coat", "rate": 0.15}], "description": "White interior sol-silicate primer that evens out absorbency.", "docs": [], "flag": "", "id": "innoprim", "name": "KEIM Innoprim", "packs": [12.5], "role": "Primer", "sds": "https://www.keim.com.au/_files/ugd/bc139a_5a91d77bafd64d7683944275e016600b.pdf", "sdsNote": "AU SDS · 02.09.2025", "tds": "https://www.keim.com.au/_files/ugd/bc139a_8d4ed8b187444b31b6154b97d8520714.pdf", "unit": "L"}, "innostar": {"about": "Interior sol-silicate paint, preservative-free, combining maximum hiding power with high yield. Suitable for all common interior wall substrates, with very good workability and a very pure white. Meets DIN 18363 2.4.1 for silicate paints and is Class 1 wet abrasion resistance to DIN EN 13300.", "application": "Brush, roller or airless spray.", "category": "Interior paint", "clause": "Apply by brush, roller or airless spray two coats of preservative-free interior sol-silicate paint to DIN 18363 2.4.1, KEIM Innostar, with wet abrasion resistance Class 1 to DIN EN 13300. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "White and many shades from the KEIM Palette exclusiv colour card.", "cons": [{"label": "Two coats", "rate": 0.18}, {"label": "One coat", "rate": 0.1}], "description": "Premium high-opacity interior sol-silicate paint. Emission- and solvent-free.", "docs": [], "flag": "", "id": "innostar", "name": "KEIM Innostar", "packs": [12.5, 5], "role": "Finish", "sds": "https://www.keim.com.au/_files/ugd/bc139a_e8b14196675845b2b5ac8ab984f11b43.pdf", "sdsNote": "AU SDS · 04.09.2025", "tds": "https://www.keim.com.au/_files/ugd/bc139a_4a8289aaa4aa41d2b9092a78fc505a0b.pdf", "unit": "L"}, "pss-20": {"about": "Sacrificial, reversible anti-graffiti coating. Graffiti is removed with hot water together with the coating, which is then re-applied.", "application": "Brush, roller or spray.", "category": "Anti-graffiti", "clause": "Apply a sacrificial anti-graffiti coating, KEIM PSS 20, to clean, dry mineral surfaces, to be removed with hot water together with any graffiti and re-applied. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "Clear.", "cons": [{"label": "One coat, dense masonry or brick", "rate": 0.2}, {"label": "One coat, porous masonry", "rate": 0.4}], "consNote": "Converted from KEIM USA data (100-200 sq ft/gal). Confirm with the AU TDS.", "description": "Sacrificial, reversible anti-graffiti coating. Removed with warm water and re-applied.", "docs": [], "flag": "", "id": "pss-20", "name": "KEIM PSS 20", "packs": [25], "role": "Protection", "sds": "https://keim-usa.com/wp-content/uploads/2024/07/SDS-PSS-20-Interservice-AG_PSS-20_50025_US-en_v1_0.pdf", "sdsNote": "US SDS · link not yet checked · no AU SDS", "tds": "https://www.keim.com.au/_files/ugd/bc139a_1cb8b424269f4e75ad88b126aed72955.pdf", "unit": "L"}, "silan-100": {"about": "Solvent-free silane water repellent for concrete and mineral surfaces. Reduces water uptake while leaving the surface vapour-open. It is not an anti-graffiti coating.", "application": "Flood-coat with a low-pressure sprayer.", "category": "Water repellent", "clause": "Apply by low-pressure flood-coating a solvent-free silane water repellent, KEIM Silan-100, to clean, dry concrete or mineral surfaces until saturated. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "Clear.", "cons": [{"label": "One flood coat", "rate": 0.18}], "description": "Solvent-free silane water repellent for concrete. Not anti-graffiti.", "docs": [], "flag": "", "id": "silan-100", "name": "KEIM Silan-100", "packs": [5], "role": "Protection", "sds": "https://www.keim.com.au/_files/ugd/bc139a_e183ed048d4d4351b23d348402a1a716.pdf", "sdsNote": "AU SDS · 05.09.2025", "tds": "https://www.keim.com/data/products/1307/723/TM_Silan-100_EN-EN.pdf", "unit": "L"}, "soldalit-fixativ": {"about": "Silica sol liquid (a combination of silica sol and potassium silicate solution in water) used to dilute the KEIM Soldalit system and its variants, and to prime dusty or highly absorbent mineral substrates. Can also be used to dilute KEIM Contact-Plus when it is followed by KEIM Soldalit.", "application": "Brush, roller or spray.", "category": "Diluent / primer", "clause": "As a preliminary fixing coat: apply by brush, roller or spray KEIM Soldalit-Fixativ, a binder based on a combination of silica sol and potassium silicate to DIN 18363 2.4.1, with organic content < 5%, specific gravity approx. 1.03 kg/L and pH approx. 11, to consolidate dusty and/or absorbent substrates and even out absorbency. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "Clear.", "cons": [{"label": "Primer coat, undiluted", "rate": 0.15}, {"label": "As diluent, per coat of paint", "rate": 0.01}], "description": "Silicate diluent and primer for highly absorbent substrates.", "docs": [], "flag": "Not on current AU range list. Confirm stock or AU equivalent.", "id": "soldalit-fixativ", "name": "KEIM Soldalit-Fixativ", "packs": [20, 5], "role": "Diluent", "sds": "https://www.keim.com.au/_files/ugd/bb7cba_43de0404e83b48279101949b2e832f3b.pdf", "sdsNote": "AU SDS · 04.09.2025", "tds": "https://www.keim.com/data/products/989/723/TM_Soldalit-Fixativ_EN-EN.pdf", "unit": "L"}, "soldalit-grob": {"about": "Filled sol-silicate facade coating to DIN 18363 2.4.1, used as a primer and intermediate coat in the KEIM Soldalit system. Evens out structural differences and closes micro-cracks on historic and modern facades, on sound old dispersion or silicone resin coatings, and on mineral substrates.", "application": "Brush or roller.", "category": "Primer / filler coat", "clause": "Apply by brush or roller one coat of filled sol-silicate primer to DIN 18363 2.4.1, KEIM Soldalit-Grob, based on a combination of silica sol and potassium silicate solution, to even out texture and close micro-cracks prior to the KEIM Soldalit finish coats. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "White, KEIM Palette exclusiv and KEIM Avantgarde. Grob shades are lighter than the colour card.", "cons": [{"label": "One coat", "rate": 0.2}, {"label": "Two coats", "rate": 0.4}], "description": "Filled silicate paint that evens texture and fills hairline crazing.", "docs": [], "flag": "", "id": "soldalit-grob", "name": "KEIM Soldalit-Grob", "packs": [18, 5], "role": "Primer", "sds": "https://www.keim.com.au/_files/ugd/bc139a_41be6d358ca94bc2918e22cd81097ed4.pdf", "sdsNote": "AU SDS · 04.09.2025", "tds": "https://www.keim.com/data/products/985/723/TM_Soldalit-Grob_EN-EN.pdf", "unit": "kg"}, "soldalit-me": {"about": "Photocatalytic sol-silicate facade paint that keeps facades cleaner for longer than conventional organic coatings. Based on silica sol and potassium silicate, pure inorganic pigments and weather-stable fillers, to DIN 18363 2.4.1, for organic, mineral and mixed substrates. Water-repellent, highly vapour-permeable, UV-resistant and highly weather-resistant with low dirt retention. Organic content < 5%.", "application": "Brush, roller or airless spray (nozzle 0.79 mm).", "category": "Facade paint", "clause": "Apply by brush or roller two coats of photocatalytic sol-silicate facade paint to DIN 18363 2.4.1, KEIM Soldalit-ME, based on a combination of silica sol and potassium silicate solution, pure inorganic pigments and weather-stable fillers, organic content < 5%. Dilute with KEIM Soldalit-Fixativ as per the technical data sheet. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "White, KEIM Exclusiv and KEIM Avantgarde colour cards. Stronger pigmentation proportionally reduces the photocatalytic effect.", "cons": [{"label": "Two coats", "rate": 0.35}, {"label": "One coat", "rate": 0.18}], "description": "Soldalit with photocatalytic effect that helps keep facades cleaner.", "docs": [], "flag": "", "id": "soldalit-me", "name": "KEIM Soldalit-ME", "packs": [18, 5], "role": "Base + finish", "sds": "https://www.keim.com.au/_files/ugd/bc139a_9b31d3c6c02c4766afd88198bd05a4cc.pdf", "sdsNote": "AU SDS · 04.09.2025", "tds": "https://www.keim.com/data/products/986/723/TM_Soldalit-ME_EN-EN.pdf", "unit": "kg"}, "soldalit": {"about": "Mineral silicate facade paint to DIN 18363 2.4.1, based on silica sol (a combination of silica sol and potassium silicate solution) and pure inorganic mineral pigments. Suitable for organic, mineral and mixed substrates.\nKEIM Soldalit is water-repellent, highly vapour-permeable, UV-resistant and extremely weather-resistant, with a low tendency to pick up dirt. It combines the advantages of a classic silicate paint with the wide application range of organically bound coatings. Organic content < 5%.", "application": "Brush, roller or airless spray (nozzle 0.79 mm).", "category": "Facade paint", "clause": "Apply by brush or roller to mineral and organic substrates two coats of sol-silicate paint to DIN 18363 2.4.1, KEIM Soldalit, based on a combination of silica sol and potassium silicate solution, pure inorganic pigments and weather-stable fillers, with water vapour diffusion resistance Class I (sd ≤ 0.01 m to DIN EN ISO 7783-2), water absorption w < 0.10 kg/(m²·h^0.5) to DIN EN 1062-3, organic content < 5% and pH approx. 11. Lightfastness A1 to BFS Data Sheet No. 26. Dilute with a maximum of 10% KEIM Soldalit-Fixativ. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "White, KEIM Palette exclusiv, KEIM Avantgarde and monochrome shades 9001–9012.", "cons": [{"label": "Two coats, with dilution", "rate": 0.35}, {"label": "Two coats, without dilution", "rate": 0.5}, {"label": "One coat", "rate": 0.2}], "description": "Sol-silicate facade paint. Bonds with mineral and sound organic substrates. Highly breathable, UV-stable inorganic pigments.", "docs": [], "flag": "", "id": "soldalit", "name": "KEIM Soldalit", "packs": [18, 5], "role": "Base + finish", "sds": "https://www.keim.com.au/_files/ugd/bc139a_4e64696671cc46cf91c8333208321c33.pdf", "sdsNote": "AU SDS · 04.09.2025", "tds": "https://www.keim.com/data/products/2633/723/TM_Soldalit_EN-EN.pdf", "unit": "kg"}, "stucasol": {"about": "Ready-to-use sol-silicate render to DIN 18363 2.4.1, with brilliant colour even without painting. For exterior facades and interiors, as a finish on mineral and organic substrates and on KEIM insulation systems.", "application": "Stainless steel trowel, float.", "category": "Decorative render", "clause": "Apply one coat of ready-mixed sol-silicate render to DIN 18363 2.4.1, KEIM Stucasol, in the specified grain size, and float to an even texture. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "KEIM colour range.", "cons": [{"label": "1 mm grain, one coat", "rate": 1.5}, {"label": "1.5 mm grain, one coat", "rate": 2.2}, {"label": "2 mm grain, one coat", "rate": 2.5}], "description": "Ready-mixed sol-silicate decorative render. No paint needed.", "docs": [], "flag": "", "id": "stucasol", "name": "KEIM Stucasol", "packs": [25], "role": "Finish", "sds": "https://www.keim.com.au/_files/ugd/bc139a_57898967d3d04839adb51b930274994c.pdf", "sdsNote": "AU SDS · 04.09.2025", "tds": "https://www.keim.com.au/_files/ugd/72d69c_5b95d079113d4b818b8bd38f0682877b.pdf", "unit": "kg"}, "twinstar": {"about": "Biocide-free sol-silicate functional coating. Its drying properties let the first coat and finish coat be applied in a single working operation without waiting between coats. Provides a high level of protection against algae and fungi without biocides, and meets DIN 18363 2.4.1. Suitable for mineral and cementitious substrates, organic substrates, existing coatings and silicone renders that are sound and well bonded. Not for timber, elastomeric coatings, oil paints or varnishes.", "application": "Brush, roller or airless spray.", "category": "Facade paint", "clause": "Apply by brush, roller or airless spray a biocide-free sol-silicate facade coating to DIN 18363 2.4.1, KEIM Twinstar, applied as base coat and finish coat in one working operation without intermediate drying time, providing protection against algae and fungal growth without the addition of biocides. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "White and the KEIM colour range.", "cons": [{"label": "Base and finish, one operation", "rate": 0.45}], "description": "Two-in-one sol-silicate facade coating applied wet-on-wet. Biocide-free.", "docs": [], "flag": "", "id": "twinstar", "name": "KEIM Twinstar", "packs": [18, 5, 2.5], "role": "Base + finish", "sds": "https://www.keim.com.au/_files/ugd/bc139a_9b6dd0bd3ea642b098bf26e9e5aaada3.pdf", "sdsNote": "AU SDS · 05.09.2025", "tds": "https://www.keim.com.au/_files/ugd/72d69c_08741f2ea3fa4b5cb083864c17661478.pdf", "unit": "kg"}, "universal-render": {"about": "Fibre-reinforced lime and hydraulic binder render with slight organic modification, for renovating and levelling old renders. Gives an ideal substrate for KEIM silicate paints.", "application": "Trowel.", "category": "Levelling render", "clause": "Level and reinforce the existing substrate with a fibre-reinforced lime-cement render, KEIM Universal Render, applied by trowel to the thickness stated in the technical data sheet, and allow to cure before coating. Including supply of materials and application, excluding scaffolding and preparatory works. Apply in accordance with the current KEIM technical data sheet.", "clauseDraft": true, "colours": "Grey or white.", "cons": [{"label": "Skim coat, about 3 mm", "rate": 3.6}], "description": "Fibre-reinforced lime-cement thin-coat render for levelling and reinforcing old renders.", "docs": [], "flag": "", "id": "universal-render", "name": "KEIM Universal Render 0.6", "packs": [20], "role": "Preparation", "sds": "https://www.keim.com.au/_files/ugd/bc139a_24da5e62dcbb45b8a7d07d13f5f9b421.pdf", "sdsNote": "AU SDS · 09.09.2025", "tds": "https://www.keim.com/data/products/1222/723/TM_Universalputz_EN-DE.pdf", "unit": "kg"}}, "systems": {"sys-acr-01": {"code": "KS-EXT-ACR-01", "conditions": "Apply at air and substrate temperatures of 5–30 °C. Do not apply in direct sun, wind, rain or on heated surfaces. Protect fresh coats from rain for 24 hours.", "environments": ["exterior"], "finish": "Matt mineral colour, opaque", "guide": {"cleanup": "Clean tools and equipment with water immediately after use. Remove splashes on glass, stone, ceramics, metal and timber straight away with plenty of clean water.", "do": ["Carry out and record an adhesion test before coating", "Protect glass, natural stone, ceramics, anodised aluminium and timber before starting", "Keep a wet edge and work to natural breaks", "Protect fresh coats from rain, strong wind and direct sun for at least 24 hours"], "dont": ["Apply below 5 °C air or substrate temperature, in direct sun or on heated surfaces", "Mix with other manufacturers' products or add water unless the TDS allows it", "Touch up small areas once dry; recoat to a natural break instead"], "method": "Apply evenly by brush, roller or airless spray, working wet edge to wet edge. Finish each elevation to natural breaks such as corners, downpipes or joints; never stop mid-wall. Brush application gives the best bond on the first coat.", "mixing": "Stir thoroughly with a paddle mixer before use and regularly during application. Where more than one container of the same colour is used, box (combine) containers first to avoid colour differences. Dilute only with the diluent stated for each coat.", "tools": ["Wide wall brush or medium-pile roller", "Drill with paddle mixer", "Masking tape, drop sheets and plastic for glass and stone", "Airless sprayer (optional, nozzle as per TDS)", "Pressure cleaner, scraper, cross-cut adhesion test kit"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Submitted for review", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Published (prototype seed)", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}], "id": "sys-acr-01", "look": "colour", "name": "Soldalit over sound acrylic paint", "notes": "If the existing coating is patchy or uneven in texture use KS-EXT-ACR-02.", "sources": "[1] Soldalit TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "", "optional": false, "product": null, "rate": 0, "stage": "Preparation", "text": "Pressure-clean to remove dirt, chalking and organic growth. Carry out a cross-cut and tape adhesion test. Remove any flaking or poorly adhered paint.", "wait": "Dry"}, {"diluent": "soldalit-fixativ", "diluentRate": 0.01, "dilution": "Up to 5% Soldalit-Fixativ", "optional": false, "product": "soldalit", "rate": 0.22, "stage": "Base coat", "text": "Brush or roll. Allow at least 12 hours before the finish coat.", "wait": "≥ 12 h"}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": false, "product": "soldalit", "rate": 0.2, "stage": "Finish coat", "text": "Brush or roll in an even, closed film.", "wait": ""}], "substrates": ["painted-acrylic"], "summary": "Converts a sound, well-adhered acrylic facade to a KEIM mineral finish without stripping. Soldalit is approved directly over dispersion coatings.", "updatedAt": "2026-09-28T09:00:00+10:00", "version": 1}, "sys-con-01": {"code": "KS-EXT-CON-01", "conditions": "Apply at air and substrate temperatures of 5–30 °C. Do not apply in direct sun, wind, rain or on heated surfaces. Protect fresh coats from rain for 24 hours.", "environments": ["exterior"], "finish": "Transparent to semi-transparent glaze, concrete texture retained", "guide": {"cleanup": "Clean tools and equipment with water immediately after use. Remove splashes on glass, stone, ceramics, metal and timber straight away with plenty of clean water.", "do": ["Approve a trial panel before starting", "Glaze whole panels or pours to natural breaks", "Record the dilution ratio and keep it identical across the project", "Protect glass, natural stone, ceramics, anodised aluminium and timber before starting"], "dont": ["Glaze in direct sun, wind or rain, or below 5 °C", "Change the dilution ratio part-way through a facade", "Apply Silan-100 after the glaze; it goes before, not after"], "method": "Brush glaze coats evenly, working in one direction and finishing each panel or pour in one go. Keep a wet edge. For more even colour, apply the second coat crosswise. Always start with a trial panel of at least 1 m² approved by the client.", "mixing": "Mix Concretal-Lasur with Concretal-Fixativ in the ratio agreed on the trial panel (1 L Lasur : 0.2–0.5 L Fixativ). Measure every batch the same way and write the ratio down. Stir regularly during use.", "tools": ["Wide glazing brush (block brush) for even glaze coats", "Drill with paddle mixer and measuring jug for dilution", "Low-pressure sprayer for Silan-100", "Masking and drop sheets"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Submitted for review", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Published (prototype seed)", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}], "id": "sys-con-01", "look": "glaze", "name": "Concretal-Lasur glaze on off-form concrete", "notes": "Glaze consumption is indicative and must be set by the trial panel. Opaque application uses about 0.25 L/m² Lasur for two coats.", "sources": "[11] Concretal-Lasur TDS  [12] Concretal-Fixativ TDS  [17] Silan-100 TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "", "optional": false, "product": null, "rate": 0, "stage": "Preparation", "text": "Remove form oil, laitance, dirt and efflorescence. Allow the concrete to cure at least 28 days. Carry out a trial panel to agree the glaze strength.", "wait": ""}, {"diluent": null, "diluentRate": 0, "dilution": "Mixed with 4.3–4.5 L water per 25 kg", "optional": true, "product": "concretal-fsp", "rate": 0.8, "stage": "Repair", "text": "Fill blowholes and pores where required. Wait 5 days before glazing.", "wait": "5 days"}, {"diluent": null, "diluentRate": 0, "dilution": "Ready to use", "optional": true, "product": "silan-100", "rate": 0.18, "stage": "Water repellent", "text": "Flood-coat with a low-pressure sprayer. Glaze after 4 hours to 1 day.", "wait": "4 h–1 day"}, {"diluent": "concretal-fixativ", "diluentRate": 0.03, "dilution": "1 L Concretal-Lasur : 0.2–0.5 L Concretal-Fixativ", "optional": false, "product": "concretal-lasur", "rate": 0.08, "stage": "Glaze coat 1", "text": "Brush application, working into the surface.", "wait": "≥ 12 h"}, {"diluent": "concretal-fixativ", "diluentRate": 0.03, "dilution": "1 L Concretal-Lasur : 0.2–0.5 L Concretal-Fixativ", "optional": false, "product": "concretal-lasur", "rate": 0.07, "stage": "Glaze coat 2", "text": "Allow at least 12 hours after coat 1.", "wait": ""}], "substrates": ["concrete-offform", "grc"], "summary": "Thin-film mineral glaze that evens out colour variation on off-form and precast concrete while keeping the concrete character.", "updatedAt": "2026-10-05T19:00:00+10:00", "version": 1}, "sys-con-02": {"code": "KS-EXT-CON-02", "conditions": "Apply at air and substrate temperatures of 5–30 °C. Do not apply in direct sun, wind, rain or on heated surfaces. Protect fresh coats from rain for 24 hours.", "environments": ["exterior", "interior"], "finish": "Opaque intense black, matt", "guide": {"cleanup": "Clean tools and equipment with water immediately after use. Remove splashes on glass, stone, ceramics, metal and timber straight away with plenty of clean water.", "do": ["Protect glass, natural stone, ceramics, anodised aluminium and timber before starting", "Keep a wet edge and work to natural breaks", "Protect fresh coats from rain, strong wind and direct sun for at least 24 hours"], "dont": ["Apply below 5 °C air or substrate temperature, in direct sun or on heated surfaces", "Mix with other manufacturers' products or add water unless the TDS allows it", "Touch up small areas once dry; recoat to a natural break instead"], "method": "Apply evenly by brush, roller or airless spray, working wet edge to wet edge. Finish each elevation to natural breaks such as corners, downpipes or joints; never stop mid-wall. Brush application gives the best bond on the first coat.", "mixing": "Stir Concretal-Black thoroughly with a paddle mixer. Box containers before use. Dilute only the base coat, with Concretal-Fixativ.", "tools": ["Wide wall brush or medium-pile roller", "Drill with paddle mixer", "Masking tape, drop sheets and plastic for glass and stone", "Airless sprayer (optional, nozzle as per TDS)"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Submitted for review", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Published (prototype seed)", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}], "id": "sys-con-02", "look": "black", "name": "Concretal-Black on concrete", "notes": "Total about 0.38 kg/m² for two coats.", "sources": "[13] Concretal-Black TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "", "optional": false, "product": null, "rate": 0, "stage": "Preparation", "text": "Remove form oil, laitance and dirt. Concrete cured at least 28 days.", "wait": ""}, {"absorbent": true, "diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": true, "product": "concretal-fixativ", "rate": 0.15, "stage": "Primer", "text": "Required on highly absorbent concrete and GRC. Apply undiluted to even out absorption.", "wait": "Dry"}, {"diluent": "concretal-fixativ", "diluentRate": 0.02, "dilution": "Up to 10% Concretal-Fixativ", "optional": false, "product": "concretal-black", "rate": 0.2, "stage": "Base coat", "text": "Brush or roll. At least 12 hours before finish coat.", "wait": "≥ 12 h"}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": false, "product": "concretal-black", "rate": 0.18, "stage": "Finish coat", "text": "", "wait": ""}], "substrates": ["concrete-offform", "concrete-int", "grc"], "summary": "Deep black mineral finish for concrete that will not fade like organic blacks.", "updatedAt": "2026-09-28T09:00:00+10:00", "version": 1}, "sys-con-03": {"code": "KS-CON-LAS-02", "conditions": "Apply at air and substrate temperatures of 5–30 °C. Do not apply in direct sun, wind, rain or on heated surfaces. Protect fresh coats from rain for 24 hours.", "environments": ["exterior", "interior"], "finish": "Transparent to semi-transparent glaze, concrete texture retained", "guide": {"cleanup": "Clean tools and equipment with water immediately after use. Remove splashes on glass, stone, ceramics, metal and timber straight away with plenty of clean water.", "do": ["Approve a trial panel before starting", "Glaze whole panels or pours to natural breaks", "Record the dilution ratio and keep it identical across the project", "Protect glass, natural stone, ceramics, anodised aluminium and timber before starting"], "dont": ["Glaze in direct sun, wind or rain, or below 5 °C", "Change the dilution ratio part-way through a facade"], "method": "Brush glaze coats evenly, working in one direction and finishing each panel or pour in one go. Keep a wet edge. For more even colour, apply the second coat crosswise. Always start with a trial panel of at least 1 m² approved by the client.", "mixing": "Mix Concretal-Lasur with Concretal-Fixativ in the ratio agreed on the trial panel (1 L Lasur : 0.2–0.5 L Fixativ). Measure every batch the same way and write the ratio down. Stir regularly during use.", "tools": ["Wide glazing brush (block brush) for even glaze coats", "Drill with paddle mixer and measuring jug for dilution", "Low-pressure sprayer for Silan-100", "Masking and drop sheets"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-10-06T11:00:00+10:00", "by": null, "version": 1}, {"action": "Published at Hoodad's request", "at": "2026-10-06T11:00:00+10:00", "by": null, "version": 1}], "id": "sys-con-03", "look": "glaze", "name": "Concretal-Lasur two-coat glaze", "notes": "Glaze consumption is indicative and must be set by the trial panel. For repairs, a water repellent or anti-graffiti protection use KS-EXT-CON-01 or KS-INT-CON-01.", "sources": "[11] Concretal-Lasur TDS  [12] Concretal-Fixativ TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "", "optional": false, "product": null, "rate": 0, "stage": "Preparation", "text": "Clean, sound concrete, cured at least 28 days. Remove form oil, laitance, dirt and efflorescence. Carry out a trial panel to agree the colour and glaze strength.", "wait": ""}, {"diluent": "concretal-fixativ", "diluentRate": 0.03, "dilution": "1 L Concretal-Lasur : 0.2–0.5 L Concretal-Fixativ", "optional": false, "product": "concretal-lasur", "rate": 0.08, "stage": "Glaze coat 1", "text": "Brush application, working into the surface.", "wait": "≥ 12 h"}, {"diluent": "concretal-fixativ", "diluentRate": 0.03, "dilution": "1 L Concretal-Lasur : 0.2–0.5 L Concretal-Fixativ", "optional": false, "product": "concretal-lasur", "rate": 0.07, "stage": "Glaze coat 2", "text": "Allow at least 12 hours after coat 1.", "wait": ""}], "substrates": ["concrete-offform", "grc", "concrete-int"], "summary": "Simple two-coat Concretal-Lasur glaze for sound, clean concrete that needs no repairs or water repellent. Evens out colour variation while keeping the concrete character.", "updatedAt": "2026-10-06T11:00:00+10:00", "version": 1}, "sys-int-01": {"code": "KS-INT-PLB-01", "conditions": "Apply at air and substrate temperatures above 5 °C. Ventilate during application and drying.", "environments": ["interior"], "finish": "Deep matt, high opacity", "guide": {"cleanup": "Clean tools with water immediately after use.", "do": ["Ventilate rooms during application and drying", "Keep a wet edge and finish each wall in one go", "Check light-critical walls with a work light before the finish coat"], "dont": ["Apply below 5 °C", "Use on yellowed plasterboard without a suitable isolating primer", "Touch up small spots; recoat the whole wall"], "method": "Cut in first, then roll in even sections, finishing each wall in one go corner to corner. Lay off in one direction for a uniform matt finish.", "mixing": "Stir Innoprim and Innostar thoroughly before use. Box containers of the same colour. The Innostar finish coat is applied undiluted.", "tools": ["Medium-pile roller (12–18 mm) and cutting-in brush", "Drill with paddle mixer", "Masking tape and drop sheets"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Submitted for review", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Published (prototype seed)", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}], "id": "sys-int-01", "look": "colour", "name": "Innoprim + Innostar (two coats)", "notes": "", "sources": "[9] Innostar TDS  [10] Innoprim TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "", "optional": false, "product": null, "rate": 0, "stage": "Preparation", "text": "Joints set and sanded to Level 4 finish or better. Remove all dust. Plaster fully dry.", "wait": ""}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": false, "product": "innoprim", "rate": 0.15, "stage": "Primer", "text": "One coat to even out absorbency. Not suitable on yellowed plasterboard.", "wait": "≥ 6 h"}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": false, "product": "innostar", "rate": 0.125, "stage": "Finish coat", "text": "Roll in an even, closed film. At least 6 hours after primer.", "wait": "≥ 6 h"}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": true, "pg3": true, "product": "innostar", "rate": 0.125, "stage": "Second finish coat", "text": "Colour group 3 (deep colours) only. Second coat of Innostar for full, even colour. Roll in an even, closed film at least 6 hours after the first finish coat.", "wait": ""}], "substrates": ["plasterboard", "plaster", "painted-int", "concrete-int", "brick", "fc-int", "aac-int", "mineral-int", "clay"], "summary": "Two-coat system: one coat of Innoprim evens out absorbency, then one finish coat of Innostar. Colour group 3 (deep colours) gets a second Innostar finish coat. Best choice for new plasterboard, patchy or unevenly absorbent surfaces and critical lighting.", "updatedAt": "2026-10-06T10:00:00+10:00", "version": 1}, "sys-int-02": {"code": "KS-INT-PLB-02", "conditions": "Apply at air and substrate temperatures above 5 °C. Ventilate during application and drying.", "environments": ["interior"], "finish": "Deep matt, high opacity", "guide": {"cleanup": "Clean tools with water immediately after use.", "do": ["Ventilate rooms during application and drying", "Keep a wet edge and finish each wall in one go"], "dont": ["Apply below 5 °C", "Use on patchy or highly absorbent surfaces; use Innoprim + Innostar instead", "Touch up small spots; recoat the whole wall"], "method": "Cut in first, then roll in even sections, finishing each wall in one go corner to corner. Lay off in one direction for a uniform matt finish.", "mixing": "Stir Innostar thoroughly. The first coat may be thinned with up to 5% water; the finish coat is applied undiluted. Box containers of the same colour.", "tools": ["Medium-pile roller (12–18 mm) and cutting-in brush", "Drill with paddle mixer", "Masking tape and drop sheets"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-09-28T12:00:00+10:00", "by": null, "version": 1}, {"action": "Published (prototype seed)", "at": "2026-09-28T12:00:00+10:00", "by": null, "version": 1}], "id": "sys-int-02", "look": "colour", "name": "Innostar + Innostar (two coats)", "notes": "Where the substrate is highly or unevenly absorbent, or under critical lighting, use KS-INT-PLB-01 with Innoprim.", "sources": "[9] Innostar TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "", "optional": false, "product": null, "rate": 0, "stage": "Preparation", "text": "Joints set and sanded to Level 4 finish or better. Existing paint clean, sound and lightly sanded. Remove all dust.", "wait": ""}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted or up to 5% water", "optional": false, "product": "innostar", "rate": 0.125, "stage": "Base coat", "text": "Roll in an even film. Allow at least 6 hours before the finish coat.", "wait": "≥ 6 h"}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": false, "product": "innostar", "rate": 0.125, "stage": "Finish coat", "text": "Roll in an even, closed film.", "wait": ""}], "substrates": ["plasterboard", "plaster", "painted-int", "concrete-int", "brick", "mineral-int"], "summary": "Two coats of Innostar with no separate primer. Suits evenly absorbent surfaces and sound existing paint.", "updatedAt": "2026-10-06T10:00:00+10:00", "version": 1}, "sys-int-con-01": {"code": "KS-INT-CON-01", "conditions": "Apply at air and substrate temperatures above 5 °C. Ventilate well during application and drying.", "environments": ["interior"], "finish": "Transparent to semi-transparent mineral glaze, concrete texture retained", "guide": {"cleanup": "Clean tools with water immediately after use. Remove splashes on glass, stone, ceramics, metal and timber straight away.", "do": ["Approve a trial panel first", "Work to natural breaks such as corners and joints", "Protect glass, natural stone, ceramics, anodised aluminium and timber before starting", "Ventilate during application and drying"], "dont": ["Change the dilution part-way through a wall", "Apply Faceal Oleo HD before the glaze has cured", "Apply below 5 °C"], "method": "Brush glaze coats evenly in one direction, finishing each wall or pour in one go. Keep a wet edge. Always start with a trial panel of at least 1 m² approved by the client.", "mixing": "Mix Concretal-Lasur with Concretal-Fixativ in the ratio agreed on the trial panel (1 L Lasur : 0.2–0.5 L Fixativ). Keep the ratio identical across the project.", "tools": ["Wide glazing brush (block brush)", "Drill with paddle mixer and measuring jug", "Brush, roller or low-pressure sprayer for Faceal Oleo HD", "Masking and drop sheets"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-10-05T19:00:00+10:00", "by": null, "version": 1}, {"action": "Published at Hoodad's request (interior range)", "at": "2026-10-05T19:00:00+10:00", "by": null, "version": 1}], "id": "sys-int-con-01", "look": "glaze", "name": "Concretal-Lasur glaze on interior concrete", "notes": "Glaze consumption is indicative and must be set by the trial panel. Check the appearance of the Faceal Oleo HD coat on the trial panel.", "sources": "[11] Concretal-Lasur TDS  [12] Concretal-Fixativ TDS  [18] Faceal Oleo HD TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "", "optional": false, "product": null, "rate": 0, "stage": "Preparation", "text": "Remove form oil, laitance, dust and efflorescence. Concrete cured at least 28 days. Carry out a trial panel to agree the glaze strength.", "wait": ""}, {"diluent": null, "diluentRate": 0, "dilution": "Mixed with 4.3–4.5 L water per 25 kg", "optional": true, "product": "concretal-fsp", "rate": 0.8, "stage": "Repair", "text": "Fill blowholes and pores where required. Wait 5 days before glazing.", "wait": "5 days"}, {"diluent": "concretal-fixativ", "diluentRate": 0.03, "dilution": "1 L Concretal-Lasur : 0.2–0.5 L Concretal-Fixativ", "optional": false, "product": "concretal-lasur", "rate": 0.08, "stage": "Glaze coat 1", "text": "Brush application, working into the surface.", "wait": "≥ 12 h"}, {"diluent": "concretal-fixativ", "diluentRate": 0.03, "dilution": "1 L Concretal-Lasur : 0.2–0.5 L Concretal-Fixativ", "optional": false, "product": "concretal-lasur", "rate": 0.07, "stage": "Glaze coat 2", "text": "Allow at least 12 hours after coat 1. Apply crosswise for more even colour.", "wait": "≥ 7 days before protection"}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": true, "product": "faceal-oleo", "rate": 0.12, "stage": "Protection coat", "text": "Optional. Clear oil, water and stain protection for kitchens, splash zones and high-touch areas. Apply once the glaze is fully cured.", "wait": "7 days to full service"}], "substrates": ["concrete-int"], "summary": "Evens out colour and patchiness on interior off-form, precast or polished-wall concrete while keeping the concrete character. Optional Faceal Oleo HD top coat for kitchens, splash zones and high-touch walls.", "updatedAt": "2026-10-05T19:00:00+10:00", "version": 1}, "sys-int-dl-01": {"code": "KS-INT-DL-01", "conditions": "Apply at air and substrate temperatures above 5 °C. Ventilate well during application and drying.", "environments": ["interior"], "finish": "Translucent decorative colour glaze, cloudy or layered effects", "guide": {"cleanup": "Clean tools with water immediately after use.", "do": ["Make and approve a sample board first", "Finish each wall in one go", "Protect glass, natural stone, ceramics, anodised aluminium and timber before starting"], "dont": ["Touch up spots afterwards", "Change the mix part-way through a wall", "Apply below 5 °C"], "method": "Glaze one wall at a time, wet in wet, finishing at corners. Build depth with extra coats rather than a stronger mix.", "mixing": "Mix Design-Lasur with Design-Base in the ratio agreed on the sample board (1:5 to 1:20). Keep the ratio identical for the whole wall.", "tools": ["Medium-pile roller and brush for Innostar", "Glazing brush, sponge or glazing tool", "Measuring jug and paddle mixer", "Masking and drop sheets"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-10-05T19:00:00+10:00", "by": null, "version": 1}, {"action": "Published at Hoodad's request (interior range)", "at": "2026-10-05T19:00:00+10:00", "by": null, "version": 1}], "id": "sys-int-dl-01", "look": "glaze", "name": "Design-Lasur glaze over Innostar", "notes": "TO CONFIRM with KEIM technical: Innostar as the base for Design-Lasur, and AU supply of Design-Base. Glaze consumption depends on the effect; set it on a sample board.", "sources": "[9] Innostar TDS  [10] Innoprim TDS  [15] Design-Lasur TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "", "optional": false, "product": null, "rate": 0, "stage": "Preparation", "text": "Substrate sound, dry and dust-free. Plasterboard to Level 4 finish or better.", "wait": ""}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": true, "product": "innoprim", "rate": 0.15, "stage": "Primer", "text": "On plasterboard, patchy or very absorbent surfaces.", "wait": "≥ 6 h"}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": false, "product": "innostar", "rate": 0.25, "stage": "Base coat", "text": "Two coats of Innostar in white or a light base colour. Allow to dry fully.", "wait": "≥ 12 h"}, {"diluent": null, "diluentRate": 0, "dilution": "1:5 to 1:20 with Design-Base", "optional": false, "product": "design-lasur", "rate": 0.017, "stage": "Glaze coat 1", "text": "Brush, sponge or glazing tool to the effect agreed on the sample board.", "wait": "≥ 12 h"}, {"diluent": null, "diluentRate": 0, "dilution": "1:5 to 1:20 with Design-Base", "optional": true, "product": "design-lasur", "rate": 0.017, "stage": "Glaze coat 2", "text": "Optional for more depth.", "wait": ""}], "substrates": ["plasterboard", "plaster", "concrete-int", "fc-int", "aac-int"], "summary": "Decorative mineral glaze for feature walls. A white or light Innostar base is glazed with Design-Lasur to give depth, cloudiness or tonal effects.", "updatedAt": "2026-10-05T19:00:00+10:00", "version": 1}, "sys-int-ole-01": {"code": "KS-INT-OLE-01", "conditions": "Apply at air and substrate temperatures above 5 °C. Ventilate well during application and drying.", "environments": ["interior"], "finish": "Clear, near-invisible permanent protection", "guide": {"cleanup": "Clean tools according to the TDS immediately after use.", "do": ["Test on a small area first", "Make sure any KEIM finish underneath is fully cured", "Ventilate during application and drying"], "dont": ["Apply on damp surfaces", "Put into service before 7 days"], "method": "Apply evenly until the surface is saturated but without runs. Apply a second coat on porous substrates.", "mixing": "Ready to use. Do not dilute. Stir before use.", "tools": ["Brush, roller or low-pressure sprayer", "Masking and drop sheets"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-10-05T19:00:00+10:00", "by": null, "version": 1}, {"action": "Published at Hoodad's request (interior range)", "at": "2026-10-05T19:00:00+10:00", "by": null, "version": 1}], "id": "sys-int-ole-01", "look": "protection", "name": "Faceal Oleo HD oil, water and stain protection", "notes": "Rates converted from KEIM USA data (sq ft/gal). Check appearance on a test area first, as it can slightly deepen the surface tone.", "sources": "[18] Faceal Oleo HD TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "", "optional": false, "product": null, "rate": 0, "stage": "Preparation", "text": "Surface or KEIM finish fully cured, clean and dry.", "wait": ""}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": false, "product": "faceal-oleo", "rate": 0.12, "stage": "Protection coat", "text": "Apply undiluted by brush, roller or low-pressure spray. Allow 24 hours between coats.", "wait": "≥ 24 h"}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": true, "product": "faceal-oleo", "rate": 0.1, "stage": "Second protection coat", "text": "On porous substrates.", "wait": "7 days to full service"}], "substrates": ["concrete-int", "brick"], "summary": "Clear, permanent oil, water and stain protection for porous interior mineral surfaces such as concrete walls, face brick, kitchen and splash-back areas and high-touch walls. Also suitable over cured Concretal-Lasur glazes.", "updatedAt": "2026-10-05T19:00:00+10:00", "version": 1}, "sys-int-sil-01": {"code": "KS-INT-SIL-01", "conditions": "Apply at air and substrate temperatures above 5 °C. Ventilate well during application and drying.", "environments": ["interior"], "finish": "Clear, invisible water repellent, surface stays vapour-open", "guide": {"cleanup": "Clean tools according to the TDS immediately after use.", "do": ["Test on a small area to check appearance", "Protect glass, natural stone, ceramics, anodised aluminium and timber before starting", "Ventilate during application and drying"], "dont": ["Apply on damp surfaces", "Expect oil or stain resistance; specify Faceal Oleo HD instead", "Apply over film-forming paints"], "method": "Flood-coat from the bottom up until the surface is saturated, wet on wet, without runs.", "mixing": "Ready to use. Do not dilute.", "tools": ["Low-pressure sprayer or wide brush", "Masking and drop sheets"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-10-05T19:00:00+10:00", "by": null, "version": 1}, {"action": "Published at Hoodad's request (interior range)", "at": "2026-10-05T19:00:00+10:00", "by": null, "version": 1}], "id": "sys-int-sil-01", "look": "protection", "name": "Silan 100 water repellent on interior concrete and masonry", "notes": "Consumption depends on porosity. Confirm on a test area. If a Concretal-Lasur glaze is planned, apply Silan 100 before the glaze, not after.", "sources": "[17] Silan-100 TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "", "optional": false, "product": null, "rate": 0, "stage": "Preparation", "text": "Surface clean, dry and free of coatings, form oil and efflorescence. Concrete cured at least 28 days.", "wait": ""}, {"diluent": null, "diluentRate": 0, "dilution": "Ready to use", "optional": false, "product": "silan-100", "rate": 0.18, "stage": "Water repellent", "text": "Flood-coat with a low-pressure sprayer or brush until saturated, wet on wet.", "wait": "Dry before use"}], "substrates": ["concrete-int", "brick"], "summary": "Clear silane treatment that reduces water uptake on exposed interior concrete and face brick, for example in basements, wet-area walls and service areas. It does not protect against oil or stains; use Faceal Oleo HD for that.", "updatedAt": "2026-10-05T19:00:00+10:00", "version": 1}, "sys-ren-01": {"code": "KS-EXT-REN-01", "conditions": "Apply at air and substrate temperatures of 5–30 °C. Do not apply in direct sun, wind, rain or on heated surfaces. Protect fresh coats from rain for 24 hours.", "environments": ["exterior"], "finish": "Matt mineral colour, opaque", "guide": {"cleanup": "Clean tools and equipment with water immediately after use. Remove splashes on glass, stone, ceramics, metal and timber straight away with plenty of clean water.", "do": ["Protect glass, natural stone, ceramics, anodised aluminium and timber before starting", "Keep a wet edge and work to natural breaks", "Protect fresh coats from rain, strong wind and direct sun for at least 24 hours"], "dont": ["Apply below 5 °C air or substrate temperature, in direct sun or on heated surfaces", "Mix with other manufacturers' products or add water unless the TDS allows it", "Touch up small areas once dry; recoat to a natural break instead"], "method": "Apply evenly by brush, roller or airless spray, working wet edge to wet edge. Finish each elevation to natural breaks such as corners, downpipes or joints; never stop mid-wall. Brush application gives the best bond on the first coat.", "mixing": "Stir thoroughly with a paddle mixer before use and regularly during application. Where more than one container of the same colour is used, box (combine) containers first to avoid colour differences. Dilute only with the diluent stated for each coat.", "tools": ["Wide wall brush or medium-pile roller", "Drill with paddle mixer", "Masking tape, drop sheets and plastic for glass and stone", "Airless sprayer (optional, nozzle as per TDS)"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Submitted for review", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Published (prototype seed)", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}], "id": "sys-ren-01", "look": "colour", "name": "Soldalit two-coat system on mineral substrates", "notes": "Total 0.35–0.50 kg/m² for two coats on smooth render. Confirm on a test area.", "sources": "[1] Soldalit TDS  [5] Soldalit-Fixativ TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "", "optional": false, "product": null, "rate": 0, "stage": "Preparation", "text": "Substrate must be sound, clean and dry. Allow new render and concrete to cure. Remove sinter skin, release agents, dust, loose material and efflorescence. Repair defects with a compatible mineral material. See the substrate note for this area.", "wait": ""}, {"absorbent": true, "diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": true, "product": "soldalit-fixativ", "rate": 0.15, "stage": "Primer", "text": "Required on highly absorbent substrates such as GRC, fibre cement, block and bagged brick. Apply undiluted to even out absorption.", "wait": "Dry"}, {"diluent": "soldalit-fixativ", "diluentRate": 0.01, "dilution": "Up to 5% Soldalit-Fixativ (10% on very absorbent render)", "optional": false, "product": "soldalit", "rate": 0.22, "stage": "Base coat", "text": "Brush or roll. Allow at least 12 hours before the finish coat.", "wait": "≥ 12 h"}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": false, "product": "soldalit", "rate": 0.2, "stage": "Finish coat", "text": "Brush or roll in an even, closed film.", "wait": ""}], "substrates": ["render-new", "render-lime", "brick", "bagged-brick", "block", "grc", "fc-sheet", "blueboard", "aac"], "summary": "Two-coat sol-silicate system for new render and mineral substrates including brick, block, GRC and fibre cement. Chemically bonds with the substrate and stays vapour-open. A Fixativ primer is added on highly absorbent substrates.", "updatedAt": "2026-09-28T09:00:00+10:00", "version": 1}, "sys-str-01": {"code": "KS-EXT-STR-01", "conditions": "Apply at air and substrate temperatures of 5–30 °C. Do not apply in direct sun, wind, rain or on heated surfaces. Protect fresh coats from rain for 24 hours.", "environments": ["exterior"], "finish": "Matt mineral colour, opaque", "guide": {"cleanup": "Clean tools and equipment with water immediately after use. Remove splashes on glass, stone, ceramics, metal and timber straight away with plenty of clean water.", "do": ["Test stripping time on a small area first", "Rinse all residue before painting", "Protect glass, natural stone, ceramics, anodised aluminium and timber before starting"], "dont": ["Apply below 5 °C air or substrate temperature, in direct sun or on heated surfaces", "Mix with other manufacturers' products or add water unless the TDS allows it"], "method": "Apply Dispersion Remover thickly, cover with plastic film, leave up to 30 hours, then scrape and wash off with hot water. Let the substrate dry fully before repairs and painting. Apply evenly by brush, roller or airless spray, working wet edge to wet edge. Finish each elevation to natural breaks such as corners, downpipes or joints; never stop mid-wall. Brush application gives the best bond on the first coat.", "mixing": "Dispersion Remover is ready to use. Stir Soldalit thoroughly and box containers.", "tools": ["Wide brush for stripper", "Plastic sheeting", "Scraper", "Hot-water pressure cleaner", "Wide wall brush or medium-pile roller", "Drill with paddle mixer"]}, "history": [{"action": "Drafted from KEIM technical data sheets", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Submitted for review", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}, {"action": "Published (prototype seed)", "at": "2026-09-28T09:00:00+10:00", "by": null, "version": 1}], "id": "sys-str-01", "look": "colour", "name": "Strip acrylic and restore with Soldalit", "notes": "Use about 1.0 kg/m² Dispersion Remover on multi-layer or elastic coatings.", "sources": "[21] Dispersion Remover  [23] Universal Render TDS", "status": "published", "steps": [{"diluent": null, "diluentRate": 0, "dilution": "Ready to use", "optional": false, "product": "dispersion-remover", "rate": 0.45, "stage": "Strip", "text": "Apply thickly by brush, cover with plastic film for up to 30 hours, scrape and wash off with hot water under pressure.", "wait": "Up to 30 h + dry"}, {"diluent": null, "diluentRate": 0, "dilution": "Mixed with water", "optional": true, "product": "universal-render", "rate": 3.6, "stage": "Repair", "text": "Level and reinforce with glass-fibre mesh where needed. Allow 5 days before painting. Rate shown for 3 mm.", "wait": "≥ 5 days"}, {"diluent": "soldalit-fixativ", "diluentRate": 0.01, "dilution": "Up to 5% Soldalit-Fixativ", "optional": false, "product": "soldalit", "rate": 0.22, "stage": "Base coat", "text": "", "wait": "≥ 12 h"}, {"diluent": null, "diluentRate": 0, "dilution": "Undiluted", "optional": false, "product": "soldalit", "rate": 0.2, "stage": "Finish coat", "text": "", "wait": ""}], "substrates": ["painted-uneven", "painted-acrylic"], "summary": "Removes failing acrylic or elastomeric coatings, restores the render and finishes in Soldalit.", "updatedAt": "2026-09-28T09:00:00+10:00", "version": 1}}, "config": {"reps": {"list": [{"email": "", "name": "Carla Galhardi", "phone": "", "states": ["NSW", "ACT"]}, {"email": "", "name": "Steve Gibson", "phone": "", "states": ["QLD", "VIC"]}], "office": {"email": "info@keim.com.au", "name": "KEIM Australia office", "phone": "(02) 9748 7160"}}}}, "pricingEnc": {"salt": "FG1w8ON6tkRePHzdMFbr1Q==", "iv": "iDs+hylb19oMy1/E", "ct": "", "iter": 200000}};
